"use client"

import * as React from "react"
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs"

import { cn } from "@/lib/utils"

import "./tabs.css"

function Tabs({ className, ...props }: TabsPrimitive.Root.Props) {
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      className={cn(
        "flex flex-col gap-3 data-[orientation=vertical]:flex-row",
        className
      )}
      {...props}
    />
  )
}

function TabsList({ className, ...props }: TabsPrimitive.List.Props) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      className={cn(
        "relative z-1 flex w-fit gap-0.5 rounded-full bg-muted p-0.5",
        "data-[orientation=vertical]:flex-col",
        className
      )}
      {...props}
    />
  )
}

function TabsTab({ className, ...props }: TabsPrimitive.Tab.Props) {
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-tab"
      className={cn(
        "relative z-10 inline-flex h-7 items-center justify-center rounded-full px-3 text-xs font-medium whitespace-nowrap text-muted-foreground outline-none select-none",
        "hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/30",
        "data-active:text-foreground",
        "data-[orientation=vertical]:w-full",
        className
      )}
      {...props}
    />
  )
}

function TabsIndicator({
  className,
  renderBeforeHydration = true,
  ...props
}: TabsPrimitive.Indicator.Props) {
  return (
    <TabsPrimitive.Indicator
      data-slot="tabs-indicator"
      renderBeforeHydration={renderBeforeHydration}
      className={cn(
        "rounded-full bg-background ring-1 ring-foreground/5 dark:ring-foreground/10",
        className
      )}
      {...props}
    />
  )
}

function TabsPanels({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="tabs-panels"
      className={cn("relative min-h-16 overflow-hidden", className)}
      {...props}
    />
  )
}

function TabsPanel({
  className,
  keepMounted = true,
  ...props
}: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-panel"
      keepMounted={keepMounted}
      className={cn("text-xs outline-none", className)}
      {...props}
    />
  )
}

export { Tabs, TabsList, TabsTab, TabsIndicator, TabsPanels, TabsPanel }

/* Ships with Tabs: the sliding indicator and the panel transitions. Imported by Tabs.tsx. */
@layer components {
  [data-slot="tabs-indicator"] {
    position: absolute;
    z-index: 0;
    top: 0;
    left: 0;
    width: var(--active-tab-width);
    height: var(--active-tab-height);
    translate: var(--active-tab-left) var(--active-tab-top);
    pointer-events: none;
    transition-property: translate, width, height;
    transition-duration: 200ms;
    transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }

  [data-slot="tabs-panels"] {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  [data-slot="tabs-panel"] {
    grid-area: 1 / 1;
  }

  [data-slot="tabs-panel"][hidden]:not([data-starting-style]):not(
      [data-ending-style]
    ) {
    display: none;
  }

  [data-slot="tabs-panel"][data-starting-style],
  [data-slot="tabs-panel"][data-ending-style] {
    display: block;
    opacity: 0;
  }

  @media (prefers-reduced-motion: no-preference) {
    [data-slot="tabs-panel"] {
      transition:
        opacity 175ms ease,
        transform 350ms cubic-bezier(0.22, 1, 0.36, 1);
    }

    [data-slot="tabs-panel"][data-starting-style][data-activation-direction="left"] {
      transform: translateX(-50%);
    }

    [data-slot="tabs-panel"][data-starting-style][data-activation-direction="right"] {
      transform: translateX(50%);
    }

    [data-slot="tabs-panel"][data-ending-style][data-activation-direction="left"] {
      transform: translateX(50%);
    }

    [data-slot="tabs-panel"][data-ending-style][data-activation-direction="right"] {
      transform: translateX(-50%);
    }

    [data-slot="tabs-panel"][data-starting-style][data-activation-direction="up"] {
      transform: translateY(-50%);
    }

    [data-slot="tabs-panel"][data-starting-style][data-activation-direction="down"] {
      transform: translateY(50%);
    }

    [data-slot="tabs-panel"][data-ending-style][data-activation-direction="up"] {
      transform: translateY(50%);
    }

    [data-slot="tabs-panel"][data-ending-style][data-activation-direction="down"] {
      transform: translateY(-50%);
    }
  }
}
